-- The API and transfer token tables of strapi-php's database (SQLite) once the tokens
-- token-import-vectors.json uses were made, for `php artisan strapi:import-tokens` to read.
CREATE TABLE strapi_api_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, document_id VARCHAR(255) DEFAULT NULL, name VARCHAR(255) DEFAULT NULL, description VARCHAR(255) DEFAULT NULL, kind VARCHAR(255) DEFAULT NULL, type VARCHAR(255) DEFAULT NULL, access_key VARCHAR(255) DEFAULT NULL, encrypted_key text DEFAULT NULL, last_used_at DATETIME DEFAULT NULL, expires_at DATETIME DEFAULT NULL, lifespan BIGINT DEFAULT NULL, created_at DATETIME DEFAULT NULL, updated_at DATETIME DEFAULT NULL, published_at DATETIME DEFAULT NULL, created_by_id INTEGER DEFAULT NULL, updated_by_id INTEGER DEFAULT NULL, locale VARCHAR(255) DEFAULT NULL);
CREATE TABLE strapi_api_token_permissions (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, document_id VARCHAR(255) DEFAULT NULL, "action" VARCHAR(255) DEFAULT NULL, created_at DATETIME DEFAULT NULL, updated_at DATETIME DEFAULT NULL, published_at DATETIME DEFAULT NULL, created_by_id INTEGER DEFAULT NULL, updated_by_id INTEGER DEFAULT NULL, locale VARCHAR(255) DEFAULT NULL);
CREATE TABLE strapi_api_token_permissions_token_lnk (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, api_token_permission_id INTEGER DEFAULT NULL, api_token_id INTEGER DEFAULT NULL, api_token_permission_ord float DEFAULT NULL, CONSTRAINT strapi_api_token_permissions_token_lnk_fk FOREIGN KEY (api_token_permission_id) REFERENCES strapi_api_token_permissions (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT strapi_api_token_permissions_token_lnk_ifk FOREIGN KEY (api_token_id) REFERENCES strapi_api_tokens (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
CREATE TABLE strapi_transfer_tokens (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, document_id VARCHAR(255) DEFAULT NULL, name VARCHAR(255) DEFAULT NULL, description VARCHAR(255) DEFAULT NULL, access_key VARCHAR(255) DEFAULT NULL, last_used_at DATETIME DEFAULT NULL, expires_at DATETIME DEFAULT NULL, lifespan BIGINT DEFAULT NULL, created_at DATETIME DEFAULT NULL, updated_at DATETIME DEFAULT NULL, published_at DATETIME DEFAULT NULL, created_by_id INTEGER DEFAULT NULL, updated_by_id INTEGER DEFAULT NULL, locale VARCHAR(255) DEFAULT NULL);
CREATE TABLE strapi_transfer_token_permissions (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, document_id VARCHAR(255) DEFAULT NULL, "action" VARCHAR(255) DEFAULT NULL, created_at DATETIME DEFAULT NULL, updated_at DATETIME DEFAULT NULL, published_at DATETIME DEFAULT NULL, created_by_id INTEGER DEFAULT NULL, updated_by_id INTEGER DEFAULT NULL, locale VARCHAR(255) DEFAULT NULL);
CREATE TABLE strapi_transfer_token_permissions_token_lnk (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, transfer_token_permission_id INTEGER DEFAULT NULL, transfer_token_id INTEGER DEFAULT NULL, transfer_token_permission_ord float DEFAULT NULL, CONSTRAINT strapi_transfer_token_permissions_token_lnk_fk FOREIGN KEY (transfer_token_permission_id) REFERENCES strapi_transfer_token_permissions (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE, CONSTRAINT strapi_transfer_token_permissions_token_lnk_ifk FOREIGN KEY (transfer_token_id) REFERENCES strapi_transfer_tokens (id) ON DELETE CASCADE NOT DEFERRABLE INITIALLY IMMEDIATE);
